<?php
require_once __DIR__ . '/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';$userId=(int)current_user()['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['mark_all'])){$st=$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?');$st->execute([$userId]);}elseif(isset($_POST['notification_id'])){$st=$pdo->prepare('UPDATE notifications SET is_read=1 WHERE notification_id=? AND user_id=?');$st->execute([(int)$_POST['notification_id'],$userId]);}flash('Notifications updated.');redirect('student/notifications.php');}
$st=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 50');$st->execute([$userId]);$notifications=$st->fetchAll();$pageTitle='Notifications';$active='dashboard';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Updates</span><h1 class="h1">Notifications</h1><p>Review assessment, evidence and roadmap updates.</p></div><form method="post"><?=csrf_field()?><button class="btn btn-outline" name="mark_all" value="1">Mark all as read</button></form></div><section class="card card-pad"><?php if(!$notifications):?><div class="empty-state"><div class="empty-icon">♧</div><h2>You're all caught up</h2><p>New updates will appear here.</p></div><?php else:foreach($notifications as $n):?><div class="activity-item"><div class="activity-dot"><?=$n['is_read']?'✓':'•'?></div><div style="flex:1"><strong><?=h($n['title'])?></strong><span><?=h($n['message'])?> · <?=date('d M Y, h:i A',strtotime($n['created_at']))?></span><?php if($n['target_url']):?><div style="margin-top:6px"><a class="link-arrow" href="<?=h(url($n['target_url']))?>">Open →</a></div><?php endif;?></div><?php if(!$n['is_read']):?><form method="post"><?=csrf_field()?><input type="hidden" name="notification_id" value="<?=(int)$n['notification_id']?>"><button class="btn btn-ghost btn-sm" type="submit">Mark read</button></form><?php endif;?></div><?php endforeach;endif;?></section></div></main><?php include __DIR__.'/../includes/footer.php';?>
